import XCTest
@testable import PhotoCraftCore

final class PixelFillStrokeTests:XCTestCase{
  func fixture(_ depth:PixelDepth = .u8)throws->CraftDocument{var d=try CraftDocument(width:20,height:16,depth:depth);var pixels=try Surface(width:20,height:16,depth:depth);for y in 4..<10{for x in 5..<12{pixels.setPixel(x:x,y:y,Pixel(0.2,0.4,0.6,0.5))}};d.layers[0].content = .raster(pixels);return d}
  func testFillOpacityModesPreservedAlphaAndUntargetedSamplesAllDepths()throws{
    for depth in PixelDepth.allCases{for mode in [BlendMode.normal,.multiply,.screen,.difference]{var d=try fixture(depth),settings=PixelPaintSettings(color:Pixel(0.8,0.3,0.2));d.selection = .init(x:7,y:6,width:3,height:2);settings.opacity=0.5;settings.mode=mode;settings.preserveTransparency=true;let source=d;try Command.pixelPaint(.init(.fill,target:.layer(d.layers[0].id),settings:settings)).apply(to:&d);guard case .raster(let out)=d.layers[0].content,case .raster(let before)=source.layers[0].content else{return XCTFail()};for y in 0..<16{for x in 0..<20{let p=out.pixel(x:x,y:y);if source.selection!.contains(x,y){XCTAssertEqual(p.a,before.pixel(x:x,y:y).a);XCTAssertTrue(p.isFinite)}else{XCTAssertTrue(p.hasSameBits(as:before.pixel(x:x,y:y)))}}};XCTAssertEqual(d.selection,source.selection);XCTAssertEqual(d.layers[0].id,source.layers[0].id)}}
  }
  func testStrokeThreeLocationsSelectionIntactAndNoSelectionUsesAlpha()throws{
    for location in PixelStrokeLocation.allCases{var d=try fixture(),settings=PixelPaintSettings(color:.white);d.selection = .init(x:5,y:4,width:7,height:6);settings.width=2;settings.location=location;let source=d;try Command.pixelPaint(.init(.stroke,target:.layer(d.layers[0].id),settings:settings)).apply(to:&d);XCTAssertEqual(d.selection,source.selection);XCTAssertNotEqual(d.layers[0].content,source.layers[0].content);guard case .raster(let out)=d.layers[0].content else{return XCTFail()};XCTAssertEqual(out.pixel(x:0,y:0),.clear)}
    var a=try fixture(),b=a,settings=PixelPaintSettings(color:.white);settings.width=2;settings.location = .outside;guard case .raster(let plane)=a.layers[0].content else{return XCTFail()};let bytes=(0..<320).map{UInt8((plane.pixel(x:$0%20,y:$0/20).a*255).rounded())};b.setCoverageSelection(try SelectionMask(width:20,height:16,bytes:bytes));let originalSelection=a.selection;try Command.pixelPaint(.init(.stroke,target:.layer(a.layers[0].id),settings:settings)).apply(to:&a);try Command.pixelPaint(.init(.stroke,target:.layer(b.layers[0].id),settings:settings)).apply(to:&b);XCTAssertEqual(a.layers,b.layers);XCTAssertEqual(a.selection,originalSelection)
  }
  func testRasterGrowthRetainsOffCanvasDataMaskPlacementAndBackgroundAlpha()throws{
    var d=try CraftDocument(width:20,height:16);var pixels=try Surface(width:5,height:4,fill:.black);pixels.setPixel(x:0,y:0,Pixel(0.7,0.1,0.2));var layer=Layer(name:"Small",content:.raster(pixels));layer.x = -2;layer.y = -1;layer.mask=try Surface(width:5,height:4,fill:.white);var properties=MaskProperties();properties.linked=false;layer.maskProperties=properties;d.layers=[layer];d.activeLayerID=layer.id;d.selection = .init(x:6,y:6,width:4,height:3);let oldMask=layer.maskCoordinateTransform;try Command.pixelPaint(.init(.fill,target:.layer(layer.id),settings:.init(color:.white))).apply(to:&d);guard case .raster(let out)=d.layers[0].content else{return XCTFail()};XCTAssertEqual(out.pixel(x:0,y:0),pixels.pixel(x:0,y:0));XCTAssertEqual(d.layers[0].maskCoordinateTransform,oldMask);XCTAssertEqual(d.layers[0].mask,layer.mask)
    var background=try fixture();background.layers[0].content = .raster(try Surface(width:20,height:16,fill:.black));background.layers[0].background=true;var settings=PixelPaintSettings(color:.white);settings.opacity=0.5;try Command.pixelPaint(.init(.fill,target:.layer(background.layers[0].id),settings:settings)).apply(to:&background);guard case .raster(let filled)=background.layers[0].content else{return XCTFail()};XCTAssertEqual(filled.pixel(x:8,y:8).a,1);XCTAssertEqual(filled.pixel(x:8,y:8).r,Float(128)/255)
  }
  func testMaskAndInvertedAuxiliaryNumericTargetsKeepColorPlanesUntouched()throws{
    for depth in PixelDepth.allCases{var d=try fixture(depth);d.layers[0].mask=try Surface(width:20,height:16,depth:depth,fill:.white);d.selection = .init(x:5,y:4,width:7,height:6);let color=d.layers[0].content;var settings=PixelPaintSettings(color:Pixel(0.4,0.4,0.4));settings.opacity=0.5;settings.mode = .multiply;try Command.pixelPaint(.init(.fill,target:.mask(d.layers[0].id),settings:settings)).apply(to:&d);XCTAssertEqual(d.layers[0].content,color);XCTAssertNotEqual(d.layers[0].mask?.pixel(x:6,y:5).r,1)
      var options=ChannelDisplayOptions();options.indicates = .selectedAreas;let channel=AlphaChannel(name:"Inverse",pixels:try Surface(width:20,height:16,depth:depth,fill:Pixel(0.2,0.2,0.2)),options:options);d.alphaChannels=[channel];let before=d;try Command.pixelPaint(.init(.fill,target:.channel(.alpha(channel.id)),settings:settings)).apply(to:&d);XCTAssertEqual(d.layers,before.layers);let old=channel.pixels.pixel(x:6,y:5).r,expected=(1-(1-old)*(1-settings.opacity+settings.opacity*0.4));XCTAssertEqual(try XCTUnwrap(d.alphaChannels?.first).pixels.pixel(x:6,y:5).r,expected,accuracy:depth == .u8 ? 0.004:0.0001);XCTAssertEqual(d.alphaChannels?[0].pixels.pixel(x:0,y:0),channel.pixels.pixel(x:0,y:0))}
  }
  func testHistoryPortableActionNativeArchiveNoOpsInvalidLocksAndCancellationAreAtomic()async throws{
    let source=try fixture();var session=EditorSession(document:source);try session.startActionRecording(name:"Paint");var settings=PixelPaintSettings(color:.white);settings.opacity=0.4;try session.execute(.pixelPaint(.init(.stroke,target:.layer(source.layers[0].id),settings:settings)));let result=session.document;XCTAssertEqual(session.undoStack.count,1);var replay=source;try XCTUnwrap(session.actionRecording?.snapshot).apply(to:&replay);XCTAssertEqual(replay,result);XCTAssertEqual(try NativeArchive.decode(NativeArchive.encodeChunked(result)),result);try session.undo();XCTAssertEqual(session.document,source);try session.redo();XCTAssertEqual(session.document,result);settings.opacity=0;try session.execute(.pixelPaint(.init(.fill,target:.layer(source.layers[0].id),settings:settings)));XCTAssertEqual(session.undoStack.count,1)
    for invalid in [-1,0,251]{var d=source;settings.width=invalid;XCTAssertThrowsError(try Command.pixelPaint(.init(.stroke,target:.layer(source.layers[0].id),settings:settings)).apply(to:&d));XCTAssertEqual(d,source)};var locked=source;locked.layers[0].protection = .image;let before=locked;settings.width=1;settings.opacity=1;XCTAssertThrowsError(try Command.pixelPaint(.init(.fill,target:.layer(source.layers[0].id),settings:settings)).apply(to:&locked));XCTAssertEqual(locked,before)
    let task=Task{while !Task.isCancelled{await Task.yield()};var d=source;try Command.pixelPaint(.init(.fill,target:.layer(source.layers[0].id),settings:.init(color:.white))).apply(to:&d)};task.cancel();do{try await task.value;XCTFail()}catch{XCTAssertTrue(error is CancellationError)}
  }
  func testSparseMaximumDocumentSmallStrokeAndImplicitFullFillDoNotMaterializeCanvas()throws{
    var d=try CraftDocument(width:300000,height:300000);d.layers[0].content = .raster(try Surface(width:300000,height:300000));d.selection = .init(x:10000,y:12000,width:4,height:4);var settings=PixelPaintSettings(color:.white);settings.width=2;settings.location = .outside;try Command.pixelPaint(.init(.stroke,target:.layer(d.layers[0].id),settings:settings)).apply(to:&d);guard case .raster(let sparse)=d.layers[0].content else{return XCTFail()};XCTAssertLessThan(sparse.allocatedBytes,2_097_152);XCTAssertEqual(sparse.pixel(x:9999,y:12001),.white);XCTAssertEqual(sparse.pixel(x:2,y:2),.clear);d.selection=nil;try Command.pixelPaint(.init(.fill,target:.layer(d.layers[0].id),settings:.init(color:.black))).apply(to:&d);guard case .raster(let filled)=d.layers[0].content else{return XCTFail()};XCTAssertEqual(filled.pixel(x:299999,y:299999),.black);XCTAssertLessThan(filled.allocatedBytes,2_097_152)
  }
  func testOwnedStrokeCoverageAndFillOutputsCapturedForIndependentReader()throws{
    var rows:[[String:Any]]=[];for location in PixelStrokeLocation.allCases{for width in [1,2,3]{var d=try CraftDocument(width:12,height:10);d.layers[0].content = .raster(try Surface(width:12,height:10));d.selection = .init(x:3,y:3,width:5,height:4);var settings=PixelPaintSettings(color:.white);settings.width=width;settings.location=location;try Command.pixelPaint(.init(.stroke,target:.layer(d.layers[0].id),settings:settings)).apply(to:&d);guard case .raster(let out)=d.layers[0].content else{return XCTFail()};rows.append(["location":location.rawValue,"width":width,"alpha":(0..<120).map{Int((out.pixel(x:$0%12,y:$0/12).a*255).rounded())}])}};if let path=ProcessInfo.processInfo.environment["PHOTATO_TEST_CAPTURE_DIR"]{let dir=URL(fileURLWithPath:path);try FileManager.default.createDirectory(at:dir,withIntermediateDirectories:true);try JSONSerialization.data(withJSONObject:["width":12,"height":10,"rows":rows],options:.sortedKeys).write(to:dir.appendingPathComponent("pixel-stroke-analytical.json"))}
  }
}
